/* Shadow Garden v2.9 — aggregate upload preflight report presentation. */
.import-preflight-report{margin-top:14px;padding-top:14px;border-top:1px solid rgba(196,184,225,.1)}
.import-report-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.import-report-head>div{display:grid;gap:2px}
.import-report-head span{color:#81778d;font-size:.56rem;font-weight:800;letter-spacing:.15em}
.import-report-head strong{color:#d7cfdf;font-size:.82rem}
.import-report-head>b{padding:5px 8px;border:1px solid rgba(196,184,225,.1);border-radius:999px;color:#a69caf;background:rgba(8,6,12,.26);font-size:.62rem;font-weight:700;white-space:nowrap}
.import-report-metrics{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}
.import-report-metrics span{padding:4px 7px;border:1px solid rgba(196,184,225,.09);border-radius:999px;color:#8f869a;background:rgba(8,6,12,.22);font-size:.6rem}
.import-report-metrics .warning{color:#d8ba84;border-color:rgba(214,181,119,.2);background:rgba(123,86,31,.08)}
.import-report-metrics .decision{color:#d2b276;border-color:rgba(205,174,111,.2);background:rgba(111,78,29,.08)}
.import-report-metrics .blocked{color:#dc99aa;border-color:rgba(215,116,142,.22);background:rgba(142,44,70,.08)}
.import-report-items{display:grid;gap:8px;margin-top:11px}
.import-report-item{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;padding:10px 11px;border:1px solid rgba(196,184,225,.09);border-radius:11px;background:rgba(8,6,12,.25)}
.import-report-item.warning{border-color:rgba(214,181,119,.16)}
.import-report-item.decision{border-color:rgba(205,174,111,.2)}
.import-report-item.blocked{border-color:rgba(215,116,142,.22);background:rgba(142,44,70,.045)}
.import-report-item-copy{min-width:0;display:grid;gap:4px}
.import-report-item-head{display:flex;align-items:center;gap:7px;min-width:0}
.import-report-item-head span{flex:0 0 auto;padding:3px 5px;border:1px solid rgba(196,184,225,.1);border-radius:6px;color:#91869f;font-size:.52rem;font-weight:800;letter-spacing:.08em}
.import-report-item.warning .import-report-item-head span{color:#d8ba84;border-color:rgba(214,181,119,.2)}
.import-report-item.decision .import-report-item-head span{color:#d2b276;border-color:rgba(205,174,111,.2)}
.import-report-item.blocked .import-report-item-head span{color:#dc99aa;border-color:rgba(215,116,142,.24)}
.import-report-item-head strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#d1c8da;font-size:.72rem}
.import-report-item p,.import-report-item small,.import-report-item em{margin:0;line-height:1.45}
.import-report-item p{color:#aaa0b4;font-size:.66rem}
.import-report-item small{display:block;color:#776f82;font-size:.59rem;overflow-wrap:anywhere}
.import-report-item em{display:block;color:#8c8297;font-size:.61rem;font-style:normal}
.import-report-item button{width:auto!important;min-width:72px!important;min-height:36px!important;margin:0!important;padding:7px 10px!important;border:1px solid rgba(184,160,229,.18)!important;border-radius:8px!important;background:rgba(123,91,177,.07)!important;color:#b9add0!important;font-size:.64rem!important;cursor:pointer}
.import-report-item button:hover,.import-report-item button:focus-visible{border-color:rgba(184,160,229,.36)!important;background:rgba(123,91,177,.13)!important;color:#d2c6e5!important}
.import-report-clean{display:flex;gap:9px;align-items:flex-start;margin-top:11px;padding:10px 11px;border:1px solid rgba(120,200,151,.14);border-radius:10px;background:rgba(45,104,66,.05)}
.import-report-clean>span{color:#98caaa;font-size:.78rem}
.import-report-clean strong,.import-report-clean small{display:block}.import-report-clean strong{color:#abc9b4;font-size:.68rem}.import-report-clean small{margin-top:3px;color:#75847a;font-size:.59rem;line-height:1.4}
.import-report-overflow{margin:8px 0 0;color:#776f82;font-size:.6rem;line-height:1.45}
@media(max-width:620px){.import-report-item{grid-template-columns:1fr;gap:8px}.import-report-item button{width:100%!important}.import-report-head{align-items:flex-start}.import-report-item-head strong{white-space:normal}}
@media(forced-colors:active){.import-report-item,.import-report-clean,.import-report-head>b,.import-report-metrics span,.import-report-item button{border:1px solid CanvasText!important}.import-report-item button:focus-visible{outline:2px solid Highlight!important}}

/* Shadow Garden v2.5 — Garden Keeper motion.
   This layer observes Keeper-owned state; it never performs requests, saves, uploads, or routing. */
@view-transition{navigation:auto}

.admin-page .admin-card,
.admin-page .manager-card,
.admin-page .maintenance-callout,
.admin-page .upload-status,
.admin-page .state-pill{
  transition:opacity var(--sg-motion-ui) var(--sg-ease-standard),transform var(--sg-motion-ui) var(--sg-ease-standard),border-color var(--sg-motion-ui) var(--sg-ease-standard),background-color var(--sg-motion-ui) var(--sg-ease-standard),box-shadow var(--sg-motion-ui) var(--sg-ease-standard);
}

.admin-dialog[open] .dialog-shell{
  animation:sg-keeper-dialog-in var(--sg-motion-layout) var(--sg-ease-enter) both;
}
.admin-dialog[open]::backdrop{
  animation:sg-keeper-backdrop-in var(--sg-motion-ui) var(--sg-ease-standard) both;
}
#dashboardView:not(.hidden) .admin-workspace{
  animation:sg-keeper-workspace-in var(--sg-motion-page) var(--sg-ease-enter) both;
}

.sg-keeper-state-changed{
  animation:sg-keeper-state-pulse 360ms var(--sg-ease-emphasized) both;
}
.sg-keeper-action-busy{
  transform:translateY(-1px);
  box-shadow:0 0 0 1px color-mix(in srgb,var(--leaf2) 22%,transparent),0 10px 26px rgba(0,0,0,.16);
}
.sg-keeper-action-settled{
  animation:sg-keeper-action-settle 420ms var(--sg-ease-enter) both;
}
.sg-keeper-list-updated > .manager-card{
  animation:sg-keeper-card-in var(--sg-motion-layout) var(--sg-ease-enter) both;
}
.sg-keeper-complete{
  animation:sg-keeper-complete 520ms var(--sg-ease-emphasized) both;
}

@keyframes sg-keeper-dialog-in{
  from{opacity:0;transform:translateY(12px) scale(.992)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
@keyframes sg-keeper-backdrop-in{from{opacity:0}to{opacity:1}}
@keyframes sg-keeper-workspace-in{
  from{opacity:0;transform:translateY(8px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes sg-keeper-state-pulse{
  0%{transform:scale(.985);filter:brightness(1)}
  45%{transform:scale(1.012);filter:brightness(1.12)}
  100%{transform:scale(1);filter:brightness(1)}
}
@keyframes sg-keeper-action-settle{
  0%{transform:translateY(-1px)}
  55%{transform:translateY(1px)}
  100%{transform:translateY(0)}
}
@keyframes sg-keeper-card-in{
  from{opacity:.35;transform:translateY(7px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes sg-keeper-complete{
  0%{transform:scale(.99);box-shadow:0 0 0 0 color-mix(in srgb,var(--leaf2) 0%,transparent)}
  45%{transform:scale(1.006);box-shadow:0 0 0 2px color-mix(in srgb,var(--leaf2) 22%,transparent)}
  100%{transform:scale(1);box-shadow:0 0 0 0 color-mix(in srgb,var(--leaf2) 0%,transparent)}
}

@media(prefers-reduced-motion:reduce){
  .admin-dialog[open] .dialog-shell,
  .admin-dialog[open]::backdrop,
  #dashboardView:not(.hidden) .admin-workspace,
  .sg-keeper-state-changed,
  .sg-keeper-action-settled,
  .sg-keeper-list-updated > .manager-card,
  .sg-keeper-complete{animation:none!important}
  .sg-keeper-action-busy{transform:none!important;box-shadow:none!important}
}

/* Garden Keeper reader-focused EPUB preflight. */
.state-pill.warning{color:#e5c98c;border-color:rgba(229,201,140,.28);background:rgba(173,132,51,.08)}
.preflight-card{position:relative;overflow:hidden}.preflight-card:before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:#6f6680}.preflight-card[data-status="pass"]:before{background:#9a86d3}.preflight-card[data-status="warning"]:before{background:#c8a562}.preflight-card[data-status="fail"]:before{background:#ce7189}
.preflight-lead{display:grid;grid-template-columns:42px minmax(0,1fr);gap:13px;align-items:start;margin-bottom:16px}.preflight-mark{width:42px;height:42px;border:1px solid rgba(196,184,225,.14);border-radius:50%;display:grid;place-items:center;background:rgba(154,134,211,.07);color:#b9abe1;font-size:1rem}.preflight-card[data-status="warning"] .preflight-mark{color:#e5c98c;background:rgba(173,132,51,.07);border-color:rgba(229,201,140,.18)}.preflight-card[data-status="fail"] .preflight-mark{color:#e5a3b4;background:rgba(139,48,72,.08);border-color:rgba(214,120,143,.2)}.preflight-lead strong{display:block;font-size:.94rem}.preflight-lead p{margin:4px 0 0;color:#91899c;font-size:.74rem;line-height:1.55}
.preflight-checks{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 13px}.preflight-check{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;border:1px solid rgba(196,184,225,.1);border-radius:999px;color:#8f8798;background:rgba(9,7,13,.25);font-size:.66rem}.preflight-check b{font-size:.75rem;font-weight:700}.preflight-check.pass{color:#b8a6e6;border-color:rgba(195,180,238,.17)}.preflight-check.warn{color:#dcc083;border-color:rgba(220,192,131,.18)}.preflight-check.fail{color:#e4a6b5;border-color:rgba(228,166,181,.2)}
.preflight-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:14px}.preflight-stats span{padding:10px;border:1px solid rgba(196,184,225,.09);border-radius:11px;background:rgba(9,7,13,.22);color:#81798b;text-align:center;font-size:.63rem;text-transform:uppercase;letter-spacing:.06em}.preflight-stats strong{display:block;margin-bottom:2px;color:#d8d1e1;font-size:.92rem;letter-spacing:0;text-transform:none}
.preflight-details{border-top:1px solid rgba(196,184,225,.09);padding-top:12px}.preflight-details summary{list-style:none;cursor:pointer;color:#aaa2b5;font-size:.72rem;display:flex;align-items:center;justify-content:space-between;gap:10px}.preflight-details summary::-webkit-details-marker{display:none}.preflight-details summary:after{content:"＋";color:#82798d}.preflight-details[open] summary:after{content:"−"}.preflight-issues{list-style:none;padding:10px 0 0;margin:0;display:grid;gap:7px}.preflight-issues li{display:grid;grid-template-columns:26px minmax(0,1fr);gap:8px;padding:9px 10px;border:1px solid rgba(196,184,225,.08);border-radius:10px;background:rgba(9,7,13,.22)}.preflight-issues li>span{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:rgba(154,134,211,.07);color:#a995d8;font-size:.72rem}.preflight-issues li.warning>span{color:#d7b66d;background:rgba(173,132,51,.08)}.preflight-issues li.fatal>span{color:#e3a0b1;background:rgba(139,48,72,.11)}.preflight-issues li.clean>span{color:#b8a6e6}.preflight-issues strong{display:block;color:#d9d3e1;font-size:.73rem;font-weight:600;line-height:1.4}.preflight-issues small{display:block;margin-top:3px;color:#81798b;font-size:.66rem;line-height:1.45;overflow-wrap:anywhere}
@media(max-width:560px){.preflight-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.preflight-checks{gap:5px}.preflight-check{padding:5px 7px}}

/* Keeper verification panel presentation. */
.admin-security-panel{margin:2px 0 14px;padding:13px;border:1px solid rgba(196,184,225,.14);border-radius:12px;background:rgba(154,134,211,.035)}
.admin-security-panel.hidden{display:none!important}.admin-security-label{margin:0 0 9px;color:#9e96a8;font-size:.68rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.admin-security-widget{min-height:66px;display:grid;align-items:center;overflow:hidden}.admin-security-status{min-height:1.35em;margin:9px 0 0;color:#81798b;font-size:.69rem;line-height:1.45}
.admin-security-status.error{color:#cf8181}.admin-security-panel[data-cooldown="true"]{border-color:rgba(207,129,129,.24);background:rgba(207,129,129,.035)}
@media(max-width:520px){.admin-security-panel{padding:11px}.admin-security-widget{min-height:62px}}

/* Shadow Garden R7 — Garden Keeper Series Editor dialog stability, Adult target controls, and toast presentation. */
.admin-dialog{box-sizing:border-box;overflow:hidden}
.admin-dialog .dialog-shell{max-height:min(88dvh,900px);min-height:0;overflow:hidden}
.admin-dialog .dialog-scroll{min-height:0;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}
#seriesEditor{height:min(88dvh,900px);max-height:min(88dvh,900px)}
#seriesEditor .dialog-shell{display:grid;grid-template-rows:auto minmax(0,1fr) auto;width:100%;height:100%;max-height:none;min-height:0}
#seriesEditor .dialog-head,#seriesEditor .dialog-actions{min-height:0}
#seriesEditor .dialog-scroll{min-height:0;height:auto;overflow-y:auto}
.adult-toggle{position:relative}
.adult-toggle>input{position:absolute!important;width:1px!important;height:1px!important;margin:0!important;padding:0!important;opacity:0!important;overflow:hidden!important;clip:rect(0 0 0 0)!important;clip-path:inset(50%)!important;white-space:nowrap!important}
.adult-toggle:focus-within{border-color:rgba(214,160,173,.34);box-shadow:0 0 0 3px rgba(183,121,139,.08)}
.keeper-targeted #metadataCard .adult-toggle{display:none!important}
.add-series-target[data-scope="adult"]{border-color:rgba(214,160,173,.28);background:rgba(183,121,139,.08)}
.add-series-target[data-scope="adult"] .add-series-target-mark{background:rgba(183,121,139,.12);color:#d6a0ad}
.admin-toast-host{position:fixed;right:max(18px,env(safe-area-inset-right));bottom:max(18px,env(safe-area-inset-bottom));z-index:1000;display:grid;gap:8px;width:min(360px,calc(100vw - 36px));pointer-events:none}
.admin-toast{box-sizing:border-box;padding:12px 14px;border:1px solid rgba(195,180,238,.22);border-radius:12px;background:rgba(20,15,28,.97);box-shadow:0 16px 45px rgba(0,0,0,.36);color:#f0edf5;font-size:.78rem;line-height:1.45;animation:adminToastIn .18s ease both}
.admin-toast.success{border-color:rgba(115,176,132,.30)}
.admin-toast.info{border-color:rgba(195,180,238,.24)}
.admin-toast.leaving{animation:adminToastOut .16s ease both}
@keyframes adminToastIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@keyframes adminToastOut{from{opacity:1;transform:none}to{opacity:0;transform:translateY(6px)}}
@media(max-width:560px){#seriesEditor{height:94dvh;max-height:94dvh}.admin-toast-host{right:18px;left:18px;width:auto}}
@media(prefers-reduced-motion:reduce){.admin-toast,.admin-toast.leaving{animation:none}}

/* Garden Pass presentation: midnight main library and rose adult wing. */
.sg-human-gate{position:fixed;z-index:10000;inset:0;width:100%;height:100%;max-width:none;max-height:none;box-sizing:border-box;margin:0;border:0;padding:20px;display:grid;place-items:center;background:rgba(4,5,5,.74);backdrop-filter:blur(12px)}
.sg-human-gate::backdrop{background:transparent}
.sg-human-card{width:min(460px,100%);padding:24px;border:1px solid rgba(196,184,225,.20);border-radius:18px;color:#f0edf5;background:linear-gradient(155deg,rgba(24,20,32,.98),rgba(9,8,13,.99));box-shadow:0 28px 90px rgba(0,0,0,.58);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
.sg-human-gate.adult .sg-human-card{border-color:rgba(214,137,160,.24);background:linear-gradient(155deg,rgba(31,16,23,.98),rgba(14,8,11,.99))}
.sg-human-mark{width:44px;height:44px;display:grid;place-items:center;margin-bottom:14px;border:1px solid rgba(196,184,225,.22);border-radius:13px;color:#c3b4ee;background:rgba(154,134,211,.06)}
.sg-human-gate.adult .sg-human-mark{color:#e0a8b8;border-color:rgba(214,137,160,.25);background:rgba(201,130,153,.07)}
.sg-human-kicker{margin:0 0 7px;color:#9a86d3;font-size:.66rem;font-weight:800;letter-spacing:.20em;text-transform:uppercase}
.sg-human-gate.adult .sg-human-kicker{color:#c98299}
.sg-human-card h2{margin:0;font:500 1.75rem/1.08 Georgia,"Times New Roman",serif;letter-spacing:-.025em}
.sg-human-copy{margin:10px 0 18px;color:#aaa2b5;font-size:.82rem;line-height:1.6}
.sg-human-gate.adult .sg-human-copy{color:#b89aa4}
.sg-human-widget{min-height:66px;display:grid;align-items:center;overflow:hidden}
.sg-human-status{min-height:1.4em;margin:12px 0 0;color:#7b7385;font-size:.72rem;line-height:1.45}
.sg-human-status.error{color:#cf8181}
.sg-human-actions{margin-top:16px;display:flex;justify-content:flex-end}
.sg-human-cancel{min-height:38px;padding:0 12px;border:1px solid rgba(196,184,225,.16);border-radius:9px;color:#aaa2b5;background:rgba(255,255,255,.025);cursor:pointer}
.sg-human-gate.adult .sg-human-cancel{border-color:rgba(214,137,160,.18);color:#b89aa4}
.sg-human-cancel:hover,.sg-human-cancel:focus-visible{color:#f0edf5;border-color:rgba(196,184,225,.30);outline:none}
@media(max-width:520px){.sg-human-gate{padding:12px}.sg-human-card{padding:20px;border-radius:15px}}
@media(prefers-reduced-motion:reduce){.sg-human-gate{backdrop-filter:none}}

/* Shadow Garden R7 — Library Recently Added, advanced filters, and archive feature layout. */
.recent-section{max-height:760px;padding:30px 0 4px;opacity:1;transform:translateY(0);overflow:hidden;transition:opacity .18s ease,transform .2s ease,max-height .26s ease,padding .26s ease}
.recent-section.results-focus{max-height:0!important;padding-top:0!important;padding-bottom:0!important;opacity:0;transform:translateY(-8px);pointer-events:none}
.catalog-main>.recent-section.results-focus{max-height:0;padding:0!important;min-height:0}
.catalog-main>.recent-section.results-focus+.catalog-bar{margin-top:0}
.recent-head{margin-bottom:16px;display:flex;align-items:end;justify-content:space-between;gap:20px}
.recent-head>div{min-width:0}.recent-head .kicker{margin-bottom:5px}.recent-head h2{margin:0;font:500 1.8rem var(--serif);letter-spacing:-.015em}
.recent-view-all{border:0;padding:7px 0;color:var(--dim);background:transparent;cursor:pointer;font-size:.74rem}.recent-view-all:hover{color:var(--leaf2)}
.recent-volumes{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:14px}
.recent-volume{min-width:0;padding:3px;border-radius:11px;text-decoration:none;display:flex;flex-direction:column;outline:none;transition:background .16s ease,transform .16s ease,box-shadow .16s ease}
.recent-volume-cover{position:relative;overflow:hidden;aspect-ratio:2/3;border:1px solid var(--line);border-radius:8px;background:linear-gradient(145deg,#172019,#0d100e);transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease}
.recent-volume:hover,.recent-volume:focus-visible{background:rgba(255,255,255,.018);transform:translateY(-1px)}
.recent-volume:hover .recent-volume-cover,.recent-volume:focus-visible .recent-volume-cover{transform:translateY(-2px);border-color:var(--line2);box-shadow:0 14px 30px rgba(0,0,0,.18)}
.recent-volume:focus-visible{outline:2px solid color-mix(in srgb,var(--leaf2) 72%,transparent);outline-offset:2px}
.recent-volume-cover img{width:100%;height:100%;display:block;object-fit:cover}
.recent-volume-fallback{position:absolute;inset:0;padding:12px;display:grid;place-items:center;text-align:center;color:#d7dfd8;font:500 .78rem/1.2 var(--serif)}
.recent-volume-fallback:before{content:"✦";position:absolute;top:17%;color:rgba(164,201,174,.22);font-size:1rem}
.recent-volume-badge{position:absolute;left:6px;bottom:6px;max-width:calc(100% - 12px);padding:4px 6px;border:1px solid rgba(255,255,255,.11);border-radius:6px;background:rgba(4,7,5,.8);color:#d9e3da;font-size:.55rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.recent-volume-copy{min-width:0;padding:9px 1px 2px;display:grid;gap:3px;align-content:start}.recent-volume-copy strong{min-width:0;display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;font:500 .78rem/1.26 var(--serif)}.recent-volume-copy span{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.recent-volume-series{margin-top:2px;color:var(--muted);font-size:.63rem}.recent-volume-added{color:var(--dim);font-size:.58rem;font-variant-numeric:tabular-nums}
.search-stack{display:grid;grid-template-columns:minmax(0,1fr);gap:6px}.search-stack>.active-filter-tags{margin-top:2px}.search-hint{margin:0 2px;color:var(--dim);font-size:.62rem;line-height:1.35}
.catalog-layout,.catalog-main,.filters,.filters>*,.search-stack,.search-field,.filter-group{min-width:0;max-width:100%}.filters,.search-stack,.search-field,.filter-group{width:100%}.filters{grid-template-columns:minmax(0,1fr)}.search-field{overflow:hidden}.search-field>span{flex:0 0 auto}.search-field input{flex:1 1 0;width:0;min-width:0;max-width:100%}.filter-group select{width:100%;min-width:0;max-width:100%}
.filter-toggle{flex:0 0 30px;width:30px;height:30px;display:grid;place-items:center;border:0;border-left:1px solid var(--line);color:var(--dim);background:transparent;cursor:pointer;font-size:.9rem}.filter-toggle:hover,.filter-toggle:focus-visible{color:var(--leaf2);outline:none}
