.skip-link{position:fixed;top:10px;left:12px;z-index:200;transform:translateY(-180%);padding:10px 14px;border:1px solid var(--line2);border-radius:9px;background:var(--panel2);color:var(--text);text-decoration:none;font-weight:700;box-shadow:0 10px 30px rgba(0,0,0,.4)}
