.nav-pinned-toggle{width:100%;min-height:40px;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:10px;border:0;border-radius:9px;color:var(--muted);background:transparent;cursor:pointer;text-align:left;font:inherit}
