.cover-reading-progress>span{transition:background-color var(--sg-motion-ui) var(--sg-ease-standard),border-color var(--sg-motion-ui) var(--sg-ease-standard),color var(--sg-motion-ui) var(--sg-ease-standard),opacity var(--sg-motion-ui) var(--sg-ease-standard),box-shadow var(--sg-motion-ui) var(--sg-ease-standard)}

