/* Progress values come from the canonical renderer. JS only animates from the
   previously-rendered width to the new renderer-owned width. */
.cover-reading-progress>span{transform-origin:left center;will-change:transform}

.series-actions .primary-button[data-volume-state]{transition:transform var(--sg-motion-fast) var(--sg-ease-standard),background-color var(--sg-motion-ui) var(--sg-ease-standard),border-color var(--sg-motion-ui) var(--sg-ease-standard),box-shadow var(--sg-motion-ui) var(--sg-ease-standard)}

@media(prefers-reduced-motion:reduce){
  #seriesRoot.sg-series-hydrated .series-info,
